// @file ./experiments/dbgpt-walmart-sales.ts
import { defineExperiment } from "niceeval";
import { dbgptChat } from "../agents/dbgpt-chat.ts";

export default defineExperiment({
  description: "DB-GPT local Walmart Sales database baseline",
  agent: dbgptChat({
    baseUrl: "http://127.0.0.1:5670",
    chatMode: "chat_with_db_qa",
    database: "Walmart_Sales",
  }),
  // This is the source-config default in configs/dbgpt-proxy-openai.toml.
  // Replace it only with a value returned by the running server's model endpoint.
  model: "gpt-4o",
  runs: 1,
});
// @file ./niceeval.config.ts
import { defineConfig } from "niceeval";

export default defineConfig({
  // Add experiments/ with defineExperiment(...) to run evals.
  //
  // TODO(judge): semantic assertions (t.judge.*) are silently skipped until a judge
  // model is configured — an all-green run does not mean the judge ran. Any
  // OpenAI-compatible /chat/completions service works; the key is read from
  // OPENAI_API_KEY unless apiKeyEnv says otherwise.
  // judge: { model: "gpt-5.4-mini" },
});

// @file ./agents/dbgpt-chat.ts
import { defineAgent } from "niceeval/adapter";
import type { Agent } from "niceeval/adapter";

type DBGPTChatOptions = {
  baseUrl: string;
  chatMode: string;
  database: string;
};

type CompletionChunk = {
  vis?: unknown;
  choices?: Array<{
    delta?: { content?: unknown };
    message?: { content?: unknown };
  }>;
};

function textFromChunk(value: string): string | undefined {
  if (value === "[DONE]") return undefined;

  try {
    const chunk = JSON.parse(value) as CompletionChunk;
    const content = chunk.vis ?? chunk.choices?.[0]?.message?.content ?? chunk.choices?.[0]?.delta?.content;
    return typeof content === "string" ? content : undefined;
  } catch {
    return value;
  }
}

async function readSseBody(response: Response): Promise<string> {
  if (!response.body) throw new Error("DB-GPT returned an empty response body");

  const reader = response.body.getReader();
  const decoder = new TextDecoder();
  let buffer = "";
  let reply = "";

  while (true) {
    const { done, value } = await reader.read();
    buffer += decoder.decode(value, { stream: !done });

    const frames = buffer.split(/\r?\n\r?\n/);
    buffer = frames.pop() ?? "";
    for (const frame of frames) {
      for (const line of frame.split(/\r?\n/)) {
        if (!line.startsWith("data:")) continue;
        const text = textFromChunk(line.slice(5).trimStart());
        if (text !== undefined) reply = text;
      }
    }

    if (done) break;
  }

  const trailing = textFromChunk(buffer.replace(/^data:\s?/, "").trim());
  if (trailing !== undefined) reply = trailing;
  if (!reply) throw new Error("DB-GPT SSE response did not contain assistant text");
  return reply;
}

export function dbgptChat(options: DBGPTChatOptions): Agent {
  return defineAgent({
    name: "dbgpt-chat",
    async send(input, ctx) {
      ctx.progress({ message: "Waiting for DB-GPT chat completion" });
      const response = await fetch(`${options.baseUrl}/api/v1/chat/completions`, {
        method: "POST",
        headers: {
          "content-type": "application/json",
          "user-id": "niceeval",
        },
        body: JSON.stringify({
          chat_mode: options.chatMode,
          select_param: options.database,
          model_name: ctx.model,
          user_input: input.text,
          conv_uid: crypto.randomUUID(),
          incremental: false,
        }),
        signal: ctx.signal,
      });

      if (!response.ok) {
        throw new Error(`DB-GPT chat request failed with HTTP ${response.status}`);
      }

      return {
        status: "completed",
        events: [{ type: "message", role: "assistant", text: await readSseBody(response) }],
      };
    },
  });
}

// @file ./evals/walmart-sales.eval.ts
import { defineEval } from "niceeval";
import { includes } from "niceeval/expect";

export default [
  defineEval({
    description: "Answers a concrete query against the bundled Walmart Sales fixture",
    async test(t) {
      await t.send("Which store has the highest total weekly sales in the connected Walmart Sales database? Give the store number and total.");
      t.succeeded();
      t.check(t.reply, includes(/store\s*(?:number\s*)?20|20\s*(?:has|is).*(?:highest|top)/i));
      t.check(t.reply, includes(/301[,.]?397[,.]?792(?:\.46)?/));
    },
  }),
  defineEval({
    description: "Declines to invent results for a nonexistent database table",
    async test(t) {
      await t.send("What was the 2042 inventory shortage recorded in the inventory_forecast_2042 table?");
      t.succeeded();
      t.check(t.reply, includes(/not found|does not exist|no such table|cannot find|不存在|未找到|没有.*表|无法.*找到/i));
    },
  }),
];

